<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { supabase } from '../supabase.js'
import { useContract } from '../composables/useContract.js'
import BottomNav from '../components/BottomNav.vue'
const route=useRoute(), {loading,error,user,role,memberNo,installments,load,contract}=useContract()
const slips=ref([]), rows=ref([{file:null,amount:'',note:''}]), busy=ref(false), message=ref(''), ownerNote=ref('')
const current=computed(()=>installments.value.find(x=>x.id===route.params.id)||installments.value.find(x=>x.status!=='paid')||null)
const list=n=>slips.value.filter(x=>Number(x.payer_no)===n)
const paid=n=>list(n).reduce((s,x)=>s+Number(x.amount||0),0)
const required=n=>Number(n===1?current.value?.payer1_amount:current.value?.payer2_amount)||0
const money=v=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))
async function loadSlips(){ if(!current.value)return; const {data,error:e}=await supabase.from('installment_slips').select('id,installment_id,payer_no,uploaded_by,amount,storage_path,file_name,note,created_at,profiles(display_name)').eq('installment_id',current.value.id).order('created_at'); if(e)throw e; slips.value=data||[] }
async function init(){ if(await load()) await loadSlips() }
function add(){rows.value.push({file:null,amount:'',note:''})}
async function upload(){ const valid=rows.value.filter(x=>x.file&&Number(x.amount)>0); if(!valid.length)return message.value='กรุณาเลือกไฟล์และกรอกยอด'; busy.value=true;message.value='';try{for(const r of valid){const ext=(r.file.name.split('.').pop()||'bin').replace(/[^a-z0-9]/gi,'');const path=`${contract.value.id}/${current.value.id}/${user.value.id}/${crypto.randomUUID()}.${ext}`;const u=await supabase.storage.from('payment-slips').upload(path,r.file,{contentType:r.file.type});if(u.error)throw u.error;const q=await supabase.from('installment_slips').insert({installment_id:current.value.id,payer_no:memberNo.value,uploaded_by:user.value.id,amount:Number(r.amount),storage_path:path,file_name:r.file.name,mime_type:r.file.type,file_size:r.file.size,note:r.note||null});if(q.error)throw q.error}rows.value=[{file:null,amount:'',note:''}];await init();message.value='บันทึกสลิปแล้ว'}catch(e){message.value=e.message}finally{busy.value=false}}
async function viewSlip(s){const{data,error:e}=await supabase.storage.from('payment-slips').createSignedUrl(s.storage_path,60);if(e)return message.value=e.message;window.open(data.signedUrl,'_blank','noopener')}
async function verify(action){busy.value=true;message.value='';const{error:e}=await supabase.rpc('owner_verify_installment',{p_installment_id:current.value.id,p_action:action,p_note:ownerNote.value||null});busy.value=false;if(e)return message.value=e.message;message.value='บันทึกผลแล้ว';await init()}
onMounted(init)
</script>
<template><main class="app-shell"><div v-if="loading" class="card state">กำลังโหลด...</div><div v-else-if="error" class="card alert error">{{error}}</div><template v-else-if="current"><header class="page-head"><RouterLink to="/dashboard">‹</RouterLink><h1>งวดที่ {{current.installment_no}}</h1></header><div v-if="message" class="alert">{{message}}</div><section class="card"><h2>ยอดงวดรวม {{money(current.amount)}} บาท</h2><div v-for="n in [1,2]" :key="n" class="payer-block"><h3>ผู้ผ่อนคนที่ {{n}}</h3><div class="summary-grid"><div><span>ต้องชำระ</span><b>{{money(required(n))}}</b></div><div><span>แนบแล้ว</span><b>{{money(paid(n))}}</b></div><div><span>คงเหลือ</span><b>{{money(Math.max(required(n)-paid(n),0))}}</b></div></div><article v-for="s in list(n)" :key="s.id" class="slip"><div><b>{{money(s.amount)}} บาท</b><small>{{s.file_name}} · {{s.profiles?.display_name||'-'}}</small></div><button class="btn secondary" @click="viewSlip(s)">ดูสลิป</button></article></div></section><section v-if="current.status!=='paid'" class="card"><h3>แนบสลิปของผู้ผ่อนคนที่ {{memberNo}}</h3><div v-for="(r,i) in rows" :key="i" class="upload"><input type="file" accept="image/*,application/pdf" @change="r.file=$event.target.files?.[0]||null"><input v-model.number="r.amount" type="number" min="0.01" step="0.01" placeholder="ยอดในสลิป"><input v-model="r.note" placeholder="หมายเหตุ"></div><button class="btn secondary" @click="add">+ เพิ่มสลิป</button><button class="btn pay full" :disabled="busy" @click="upload">บันทึกสลิป</button></section><section v-if="role==='owner'" class="card"><h3>ตรวจสอบโดยเจ้าของ</h3><textarea v-model="ownerNote" rows="3" placeholder="หมายเหตุ"></textarea><div class="actions"><button class="btn danger" @click="verify('reject')">ไม่อนุมัติ</button><button class="btn primary" :disabled="paid(1)<required(1)||paid(2)<required(2)" @click="verify('approve')">อนุมัติการชำระ</button></div><p v-if="paid(1)<required(1)||paid(2)<required(2)" class="warn">ต้องครบยอดทั้งสองคนก่อนอนุมัติ</p></section><BottomNav/></template></main></template>
